        /* sdd-asis-lifecycle:begin btn_modify_2_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.modify('' + dma_lecrDiptList.get("eduApplSeq") + '')
        /* sdd-asis-lifecycle:end */

