/**
 * @event
 * @name scwin.btn_goList_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_goList_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_goList_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.goList()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30603.btn_goList_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_goList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_goList = async function () {
    const sbmOptions = {
        id: "tx_fn_goList",
        method: "post",
        action: "/issue/lecrDipt.do",
        ref: "dma_goListReq",
        target: "dlt_lecrDiptSchdl=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil30603.tx_fn_goList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_modify = async function () {
    const sbmOptions = {
        id: "tx_fn_modify",
        method: "post",
        action: "/issue/lecrDipt.do",
        ref: "dma_modifyReq",
        target: "dlt_lecrDiptSchdl=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil30603.tx_fn_modify" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.goList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goList = async function () {
    /* sdd-asis-lifecycle:begin fn_goList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.LecrDiptForm || { elements: [] });
    frm.action = 'lecrDipt.do';
    $c.util.getComponent('dma_goListReq').set('method', 'searchLecrDipt');
    { const nr = await scwin.tx_fn_goList(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil30601/jldfil30601.xml", { "method": 'searchLecrDipt' }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param eduApplSeq
 * @returns
 * @hidden N
*/
scwin.modify = async function (eduApplSeq) {
    /* sdd-asis-lifecycle:begin fn_modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.LecrDiptForm || { elements: [] });
    frm.action = 'lecrDipt.do';
    $c.util.getComponent('dma_goListReq').set('method', 'modifyLecrDipt');
    $c.util.getComponent('dma_goListReq').set('modifyYn', 'Y');
    $c.util.getComponent('dma_goListReq').set('eduApplSeq', eduApplSeq);
    { const nr = await scwin.tx_fn_modify(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil30604/jldfil30604.xml", { "method": 'modifyLecrDipt', "modifyYn": 'Y', "eduApplSeq": eduApplSeq }); } };
    /* sdd-asis-lifecycle:end */
};
